const lists = $.steps.getLists.response || [];
const action = $.input.action;
const listName = $.input.listName;
const listId = $.input.listId;

const listMap = (Array.isArray(lists) ? lists : []).map(l => ({ id: l.id, name: l.name }));

let resolvedListId = listId;
if (!resolvedListId && listName) {
  const match = listMap.find(l => l.name.toLowerCase() === listName.toLowerCase());
  if (match) resolvedListId = match.id;
  else throw new Error(`List "${listName}" not found. Available lists: ${listMap.map(l => l.name).join(', ')}`);
}

return { action, resolvedListId, listMap, isCreate: action === 'create' };

const action = $.steps.resolveListAndRoute.output.action;
const listMap = $.steps.resolveListAndRoute.output.listMap;

if (action === 'create') {
  const card = $.steps.createCard?.response || {};
  return {
    action: 'create',
    card: {
      id: card.id || '',
      name: card.name || '',
      url: card.shortUrl || card.url || '',
      list: listMap.find(l => l.id === card.idList)?.name || card.idList || '',
      due: card.due || null
    },
    summary: card.id ? `Created card "${card.name}" on list "${listMap.find(l => l.id === card.idList)?.name || 'unknown'}"` : 'Failed to create card'
  };
} else {
  const cards = $.steps.getCards?.response || [];
  const formatted = (Array.isArray(cards) ? cards : []).map(c => ({
    id: c.id || '',
    name: c.name || '',
    list: listMap.find(l => l.id === c.idList)?.name || c.idList || '',
    url: c.shortUrl || c.url || '',
    due: c.due || null,
    closed: c.closed || false
  }));
  return {
    action: 'list',
    cards: formatted,
    totalCards: formatted.length,
    lists: listMap,
    summary: `Found ${formatted.length} card${formatted.length === 1 ? '' : 's'} across ${listMap.length} list${listMap.length === 1 ? '' : 's'}`
  };
}
